        pass

    @abstractmethod
    def search_short_term_memory(self, query: str, user_id: str, limit: int) -> List[Dict]:
        pass

    @abstractmethod
    def find_short_term_memory_by_id(self, memory_id: str, user_id: str) -> Optional[Dict]:
        pass

    @abstractmethod
    def mark_conscious_memories_processed(self, memory_ids: List[str], user_id: str) -> bool:
