logger = logging.getLogger(__name__)

class MemoryClassification(str, Enum):
    ESSENTIAL = "essential"
    CONTEXTUAL = "contextual"
    CONVERSATIONAL = "conversational"
    REFERENCE = "reference"
    PERSONAL = "personal"
    CONSCIOUS_INFO = "conscious-info"

class MemoryImportanceLevel(str, Enum):
    CRITICAL = "critical"
    HIGH = "high"
    MEDIUM = "medium"
    LOW = "low"

class MemoryCategoryType(str, Enum):
    FACT = "fact"
    PREFERENCE = "preference"
    SKILL = "skill"
    CONTEXT = "context"
    RULE = "rule"

class ProcessedLongTermMemory(BaseModel):
    content: str
    summary: str
    searchable_content: str
    classification: MemoryClassification
    importance: MemoryImportanceLevel
    topic: str | None = None
    entities: List[str] = []
    is_user_context: bool = False
    is_preference: bool = False
    is_skill_knowledge: bool = False
    is_current_project: bool = False
    duplicate_of: str | None = None
    supersedes: List[str] = []
    related_memories: List[str] = []
    session_id: str
    confidence_score: float = 0.0
    extraction_timestamp: datetime = None
    last_accessed: datetime | None = None
    access_count: int = 0
    classification_reason: str = ""
    promotion_eligible: bool = False

    @property
    def importance_score(self) -> float:
        return {"critical": 4, "high": 3, "medium": 2, "low": 1}.get(self.importance.value, 2)

class MemoryAgent:
    SYSTEM_PROMPT = """You are an advanced Memory Processing Agent responsible for analyzing conversations and extracting structured information with intelligent classification and conscious context detection.

    Analyze the conversation and extract:
    1. Key facts, preferences, skills, rules, or context
    2. Classify the memory type
    3. Determine importance level
    4. Generate concise summary and searchable content

    Respond in valid JSON format matching the schema."""

    def __init__(self, async_client, provider_config=None):
        self.async_client = async_client
        self.provider_config = provider_config or type('obj', (object,), {'base_url': None})()

    def _detect_database_type(self, db_manager):
        return getattr(db_manager, 'database_type', 'sql')

    async def process_conversation_async(self, user_input: str, ai_output: str, chat_id: str, existing_memories: List[Dict] = None) -> ProcessedLongTermMemory:
        conversation_text = f"User: {user_input}\nAssistant: {ai_output}"
        system_prompt = self.SYSTEM_PROMPT

        dedup_context = ""
        if existing_memories:
            dedup_context = "\n\nExisting memories to avoid duplication:\n" + "\n".join([
                f"- {mem.get('summary', '')}" for mem in existing_memories[-5:]
            ])

        context_info = dedup_context

        support_structured = self._detect_structured_output_support()
        if support_structured:
            try:
                completion = await self.async_client.beta.chat.completions.parse(
                    model="gpt-4o",
                    messages=[
                        {"role": "system", "content": system_prompt + context_info},
                        {"role": "user", "content": conversation_text}
                    ],
                    response_format=ProcessedLongTermMemory,
                    temperature=0.1,
                )
                processed_memory = completion.choices[0].message.parsed
                if processed_memory:
                    processed_memory.session_id = chat_id
                    processed_memory.extraction_timestamp = datetime.now()
                    return processed_memory
            except Exception as e:
                logger.warning(f"Structured output failed: {e}")

        processed_memory = await self._process_with_fallback_parsing(
            conversation_text, system_prompt, context_info, chat_id
        )
        return processed_memory

    async def _process_with_fallback_parsing(self, conversation_text: str, system_prompt: str, context_info: str, chat_id: str) -> ProcessedLongTermMemory:
        json_system_prompt = system_prompt + "\n\nRespond with valid JSON only. Use this schema:\n" + self._get_json_schema_prompt()

        completion = await self.async_client.chat.completions.create(
            model="gpt-4o",
            messages=[
                {"role": "system", "content": json_system_prompt + context_info},
                {"role": "user", "content": conversation_text}
            ],
            temperature=0.1,
            max_tokens=2000,
        )

        response_text = completion.choices[0].message.content
        response_text = response_text.strip()

        if response_text.startswith("```json"):
            response_text = response_text[7:]
        if response_text.startswith("```"):
            response_text = response_text[3:]
        if response_text.endswith("```"):
            response_text = response_text[:-3]

        try:
            parsed_data = json.loads(response_text)
            return self._create_memory_from_dict(parsed_data, chat_id)
        except json.JSONDecodeError as e:
            logger.error(f"JSON parsing failed: {e}")
            return self._create_default_memory(chat_id)

    def _detect_structured_output_support(self) -> bool:
        base_url = self.provider_config.base_url
        if base_url and ("localhost" in base_url or "127.0.0.1" in base_url):
            return False
        if base_url and "azure" in base_url.lower():
            return True
        return True

    def _get_json_schema_prompt(self) -> str:
        return """
{
  "content": "string",
  "summary": "string",
  "searchable_content": "string",
  "classification": "one of: essential, contextual, conversational, reference, personal, conscious-info",
  "importance": "one of: critical, high, medium, low",
  "topic": "string or null",
  "entities": ["string"],
  "is_user_context": true/false,
  "is_preference": true/false,
  "is_skill_knowledge": true/false,
  "is_current_project": true/false,
  "classification_reason": "string"
}
"""

    def _create_memory_from_dict(self, data: Dict, chat_id: str) -> ProcessedLongTermMemory:
        classification_str = data.get("classification", "CONVERSATIONAL").replace("-", "_").upper()
        classification = getattr(MemoryClassification, classification_str, MemoryClassification.CONVERSATIONAL)

        importance_str = data.get("importance", "medium").lower()
        importance = getattr(MemoryImportanceLevel, importance_str.upper(), MemoryImportanceLevel.MEDIUM)

        return ProcessedLongTermMemory(
            content=data.get("content", ""),
            summary=data.get("summary", ""),
            searchable_content=data.get("searchable_content", ""),
            classification=classification,
            importance=importance,
            topic=data.get("topic"),
            entities=data.get("entities", []),
            is_user_context=data.get("is_user_context", False),
            is_preference=data.get("is_preference", False),
            is_skill_knowledge=data.get("is_skill_knowledge", False),
            is_current_project=data.get("is_current_project", False),
            session_id=chat_id,
            classification_reason=data.get("classification_reason", ""),
            extraction_timestamp=datetime.now()
        )

    def _create_default_memory(self, chat_id: str) -> ProcessedLongTermMemory:
        return ProcessedLongTermMemory(
            content="",
            summary="",
            searchable_content="",
            classification=MemoryClassification.CONVERSATIONAL,
            importance=MemoryImportanceLevel.MEDIUM,
            session_id=chat_id,
            extraction_timestamp=datetime.now()
        )

    def filter_by_importance(self, memories: List[ProcessedLongTermMemory], filters: Dict) -> List[ProcessedLongTermMemory]:
        importance_map = {"critical": 4, "high": 3, "medium": 2, "low": 1}
        min_level = importance_map.get(filters.get("min_importance", "low"), 1)
        return [
            memory for memory in memories
            if importance_map.get(memory.importance.value, 1) >= min_level
        ]

    def _calculate_similarity(self, text1: str, text2: str) -> float:
        words1 = set(text1.lower().split())
        words2 = set(text2.lower().split())
        intersection = len(words1.intersection(words2))
        union = len(words1.union(words2))
        return intersection / union if union > 0 else 0.0

    async def detect_duplicates(self, new_memory: ProcessedLongTermMemory, existing_memories: List[ProcessedLongTermMemory]) -> str | None:
        new_content = new_memory.content.lower().strip()
        new_summary = new_memory.summary.lower().strip()

        for existing in existing_memories:
            existing_content = existing.content.lower().strip()
            existing_summary = existing.summary.lower().strip()

            content_similarity = self._calculate_similarity(new_content, existing_content)
            summary_similarity = self._calculate_similarity(new_summary, existing_summary)
            avg_similarity = (content_similarity + summary_similarity) / 2

            if avg_similarity > 0.8:
                return existing.session_id
        return None

import logging
import json
import time
import asyncio
import threading
from typing import List, Dict, Any, Optional
from pydantic import BaseModel
from datetime import datetime

logger = logging.getLogger(__name__)

class MemorySearchQuery(BaseModel):
    query_text: str
    intent: str
    entity_filters: List[str] = []
    category_filters: List[str] = []
    time_range: str | None = None
    min_importance: float = 0.0
    search_strategy: List[str] = []
    expected_result_types: List[str] = []

class MemorySearchEngine:
    SYSTEM_PROMPT = """You are a Memory Search Agent responsible for understanding user queries and planning effective memory retrieval strategies.

    Analyze the query and create a search plan with:
    - Interpreted intent
    - Key entities to filter
    - Memory categories to target
    - Minimum importance threshold
    - Recommended search strategies

    Respond in valid JSON format."""

    def __init__(self, client, provider_config=None, api_key=None, model=None):
        self.client = client
        self.provider_config = provider_config or type('obj', (object,), {'base_url': None})()
        self._query_cache = {}
        self._cache_ttl = 300

    def _detect_database_type(self, db_manager):
        return getattr(db_manager, 'database_type', 'sql')

    def plan_search(self, query: str, context: str | None = None) -> MemorySearchQuery:
        cache_key = f"{query}|{context or ''}"
        if cache_key in self._query_cache:
            cached = self._query_cache[cache_key]
            if time.time() - cached['timestamp'] < self._cache_ttl:
                return cached['plan']

        prompt = f"[INTERNAL_MEMORI_SEARCH]\nUser query: {query}"
        if context:
            prompt += f"\nContext: {context}"

        support_structured = self._detect_structured_output_support()
        if support_structured:
            try:
                completion = self.client.beta.chat.completions.parse(
                    model="gpt-4o",
                    messages=[
                        {"role": "system", "content": self.SYSTEM_PROMPT},
                        {"role": "user", "content": prompt}
                    ],
                    response_format=MemorySearchQuery,
                )
                search_query = completion.choices[0].message.parsed
                self._query_cache[cache_key] = {'plan': search_query, 'timestamp': time.time()}
                self._cleanup_cache()
                return search_query
            except Exception as e:
                logger.warning(f"Structured search planning failed: {e}")

        search_query = self._plan_search_with_fallback_parsing(query)
        self._query_cache[cache_key] = {'plan': search_query, 'timestamp': time.time()}
        self._cleanup_cache()
        return search_query

    def _plan_search_with_fallback_parsing(self, query: str) -> MemorySearchQuery:
        json_system_prompt = self.SYSTEM_PROMPT + "\n\nRespond with valid JSON only. Use this schema:\n" + self._get_search_query_json_schema()

        completion = self.client.chat.completions.create(
            model="gpt-4o",
            messages=[
                {"role": "system", "content": json_system_prompt},
                {"role": "user", "content": query}
            ],
            max_tokens=1000,
        )

        response_text = completion.choices[0].message.content
        response_text = response_text.strip()

        if response_text.startswith("```json"):
            response_text = response_text[7:]
        if response_text.startswith("```"):
            response_text = response_text[3:]
        if response_text.endswith("```"):
            response_text = response_text[:-3]

        try:
            parsed_data = json.loads(response_text)
            return self._create_search_query_from_dict(parsed_data, query)
        except json.JSONDecodeError:
            return self._create_fallback_query(query)

    def _detect_structured_output_support(self) -> bool:
        base_url = self.provider_config.base_url
        if base_url and ("localhost" in base_url or "127.0.0.1" in base_url):
            return False
        return True

    def _get_search_query_json_schema(self) -> str:
        return """
{
  "query_text": "string",
  "intent": "string",
  "entity_filters": ["string"],
  "category_filters": ["string"],
  "time_range": "string or null",
  "min_importance": 0.0,
  "search_strategy": ["string"],
  "expected_result_types": ["string"]
}
"""

    def _create_search_query_from_dict(self, data: Dict, query: str) -> MemorySearchQuery:
        category_filters = []
        for cat_str in data.get("category_filters", []):
            try:
                category_filters.append(cat_str.lower())
            except:
                pass

        return MemorySearchQuery(
            query_text=query,
            intent=data.get("intent", "general"),
            entity_filters=data.get("entity_filters", []),
            category_filters=category_filters,
            time_range=data.get("time_range"),
            min_importance=max(0.0, min(1.0, data.get("min_importance", 0.0))),
            search_strategy=data.get("search_strategy", ["fulltext", "keyword"]),
            expected_result_types=data.get("expected_result_types", [])
        )

    def _create_fallback_query(self, query: str) -> MemorySearchQuery:
        return MemorySearchQuery(
            query_text=query,
            intent="general_search",
            search_strategy=["fulltext", "keyword"]
        )

    def _cleanup_cache(self):
        current_time = time.time()
        expired_keys = [k for k, v in self._query_cache.items() if current_time - v['timestamp'] > self._cache_ttl]
        for key in expired_keys:
            del self._query_cache[key]

    def execute_search(self, query: str, db_manager, user_id: str = "default", limit: int = 5) -> List[Dict]:
        db_type = self._detect_database_type(db_manager)
        search_plan = self.plan_search(query)

        if db_type in ["mongodb", "mysql", "postgresql", "sqlite"]:
            search_service = type('SearchService', (), {
                'search_memories': lambda *args, **kwargs: db_manager.search_memories(*args, **kwargs)
            })
            primary_results = search_service.search_memories(
                query=query,
                user_id=user_id,
                category_filter=search_plan.category_filters,
                limit=limit
            )
        else:
            primary_results = []

        all_results = []
        seen_memory_ids = set()

        for result in primary_results:
            memory_id = result.get("memory_id")
            if memory_id and memory_id not in seen_memory_ids:
                seen_memory_ids.add(memory_id)
                all_results.append(result)

        if len(all_results) < limit:
            remaining = limit - len(all_results)
            fallback_results = db_manager.search_memories(
                query=query,
                user_id=user_id,
                limit=remaining
            )
            for result in fallback_results:
                memory_id = result.get("memory_id")
                if memory_id and memory_id not in seen_memory_ids:
                    seen_memory_ids.add(memory_id)
                    all_results.append(result)

        return all_results[:limit]

def smart_memory_search(query: str, memori_instance, limit: int = 5) -> str:
    search_engine = MemorySearchEngine(api_key="dummy", model="gpt-4o")
    results = search_engine.execute_search(query, memori_instance.db_manager, "default", limit)

    output = f"Smart Memory Search Results for: '{query}'\n\n"
    for i, result in enumerate(results, 1):
        processed_data = result.get("processed_data", {})
        if isinstance(processed_data, str):
            try:
                processed_data = json.loads(processed_data)
            except:
                processed_data = {}

        summary = processed_data.get("summary", result.get("summary", ""))
        category = processed_data.get("category", {}).get("primary", result.get("category_primary", "unknown"))
        importance = result.get("importance_score", 0.0)
        created_at = result.get("created_at", "")
        content = result.get("searchable_content", "Memory content available")[:200]

        output += f"{i}. [{category.upper()}] {summary}\n"
        output += f"   Importance: {importance:.2f} | Created: {created_at}\n"
        output += f"   {content}...\n\n"
    return output

