    shared_memory: bool = Field(default=False, description="Enable shared memory across users")
    retention_policy: RetentionPolicy = Field(default=RetentionPolicy.DAYS_30)
    auto_cleanup: bool = Field(default=True, description="Enable automatic cleanup")
    cleanup_interval_hours: int = Field(default=24, ge=1, le=720)
    importance_threshold: float = Field(default=0.3, ge=0.0, le=1.0)
    max_short_term_memories: int = Field(default=100, ge=10, le=1000)
