from dataclasses import dataclass, field
from datetime import datetime
from typing import List, Dict, Any
import uuid

@dataclass
class ConversationMessage:
    role: str
    content: str
    timestamp: datetime = field(default_factory=datetime.now)
    metadata: Dict[str, Any] = field(default_factory=dict)

@dataclass
class ConversationSession:
    session_id: str
    messages: List[ConversationMessage] = field(default_factory=list)
    context_injected: bool = False
    created_at: datetime = field(default_factory=datetime.now)
    last_accessed: datetime = field(default_factory=datetime.now)

    def add_message(self, role: str, content: str, metadata: Dict[str, Any] = None):
        message = ConversationMessage(
            role=role,
            content=content,
            metadata=metadata or {}
        )
        self.messages.append(message)
        self.last_accessed = datetime.now()

    def get_history_messages(self, limit: int = 10) -> List[Dict[str, str]]:
        recent_messages = self.messages[-limit:]
        return [
            {"role": msg.role, "content": msg.content}
            for msg in recent_messages
        ]

class ConversationManager:
    def __init__(self, max_sessions: int = 100):
        self.sessions = {}
        self.max_sessions = max_sessions

    def get_or_create_session(self, session_id: str = None) -> ConversationSession:
        if session_id and session_id in self.sessions:
            return self.sessions[session_id]

        session_id = session_id or str(uuid.uuid4())
        if len(self.sessions) >= self.max_sessions:
            oldest_session_id = min(self.sessions, key=lambda k: self.sessions[k].last_accessed)
            del self.sessions[oldest_session_id]

        session = ConversationSession(session_id=session_id)
        self.sessions[session_id] = session
        return session

